CATALOG={"GERBER_ARC_INVALID":"Gerber arc geometry is inconsistent.","GERBER_REGION_OPEN":"Gerber region was not closed.","GERBER_REGION_CUTIN_INVALID":"Gerber cut-in geometry violates the supported fully-coincident axis-aligned bridge rules.","GERBER_REGION_CUTIN_DIRECTION_MISMATCH":"All cut-ins in one contour must share one horizontal or vertical direction.","GERBER_REGION_CUTIN_WINDING_INVALID":"Cut-in hole winding must oppose the enclosing shell.","GERBER_REGION_CUTIN_TOUCH_INVALID":"Cut-in bridges may contact contour boundaries only at their endpoints.","GERBER_REGION_CUTIN_DISJOINT_UNSUPPORTED":"A fully-coincident cut-in that resolves to disjoint filled areas is not modeled yet.","APERTURE_MACRO_UNSUPPORTED":"Aperture macro contains unsupported semantics.","KICAD_PARSE_ERROR":"KiCad S-expression input could not be parsed.","MULTILAYER_SPAN_UNKNOWN":"Layer span is not established by evidence.","X2_DRILL_SPAN_UNRESOLVED":"Explicit X2 drill layer span cannot be mapped safely onto the reconstructed copper stack.","X2_SLOT_SPAN_UNRESOLVED":"Explicit X2 slot layer span cannot be mapped safely onto the reconstructed copper stack.","X2_ROUTE_SPAN_UNRESOLVED":"Explicit X2 routed-path layer span cannot be mapped safely onto the reconstructed copper stack."}
def message_for(code): return CATALOG.get(str(code),"Unknown diagnostic code.")
